L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP15_ACT4_EPILOGUE2@16#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 743
L23_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "내 손으로 만든 현실이지. 엄마는 그렇게 죽었어. 그 사실은 변하지 않아."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "私の手で作った現実。お母さんはそうやって死んだ。その事実は変わらない。"
L23_1.m_Talk_ENG = "It's a reality I created with my own hands. That's how my mother died. That truth doesn't change."
L23_1.m_Talk_TWN = "那是我親手造就的現實。媽媽就是那樣死去的，這件事不會改變。"
L23_1.m_Talk_DEU = "It's a reality I created with my own hands. That's how my mother died. That truth doesn't change."
L23_1.m_Talk_FRA = "It's a reality I created with my own hands. That's how my mother died. That truth doesn't change."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP15_ACT4_EPILOGUE2@17#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 743
L24_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_SERIOUS"
L24_1.m_CharStrID = "ROOKIE_GRONIA_NULL_NULL"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "네퀴티아잖아요. 그런 짓을 한 건 당신이 아니라고요."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "ネキティアですよ。それをやったのはあなたじゃありません。"
L24_1.m_Talk_ENG = "It was Nequitia. You weren't the one who did it."
L24_1.m_Talk_TWN = "那是莉奎蒂亞做的，不是你的錯。"
L24_1.m_Talk_DEU = "It was Nequitia. You weren't the one who did it."
L24_1.m_Talk_FRA = "It was Nequitia. You weren't the one who did it."
