L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 743
L26_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L26_1.m_Pos = "C"
L26_1.m_Talk_KOREA = "하지만 이 죄를 안고 살아가는 건, 내 나름의 복수이기도 해."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "でもこの罪を背負って生きるのは、自分なりの復讐でもあるの。"
L26_1.m_Talk_ENG = "But living with that guilt is my way of taking revenge."
