L26_1.m_Talk_FRA = "But living with that guilt is my way of taking revenge."
L27_1 = {}
L27_1.m_CutScenKey_Talk = "EP15_ACT4_EPILOGUE2@20#Talk"
L27_1.m_CutScenProcessKey = 27
L27_1.m_CutScenID = 743
L27_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "ROOKIE_GRONIA_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "아픔을 잊지 않는 게... 어떻게 복수가 된다는 거죠?"
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "痛みを忘れないことが……どうして復讐になるんですか？"
L27_1.m_Talk_ENG = "How does refusing to forget the pain... become revenge?"
L27_1.m_Talk_TWN = "不忘記痛苦……怎麼會是復仇呢？"
L27_1.m_Talk_DEU = "How does refusing to forget the pain... become revenge?"
L27_1.m_Talk_FRA = "How does refusing to forget the pain... become revenge?"
L28_1 = {}
L28_1.m_CutScenKey_Talk = "EP15_ACT4_EPILOGUE2@21#Talk"
L28_1.m_CutScenProcessKey = 28
L28_1.m_CutScenID = 743
L28_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L28_1.m_Pos = "C"
L28_1.m_Talk_KOREA = "내가 그 현실을 어쩔 수 없는 것이라 부정하거나 잊어버리면, 네퀴티아도 그걸 잊게 될 테니까."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "私があの現実を「仕方ない」と否定したり忘れたりしたら、ネキティアもそれを忘れるだろうから。"
L28_1.m_Talk_ENG = "Because if I deny it or forget it as something unavoidable, then Nequitia would forget it too."
L28_1.m_Talk_TWN = "如果我把那件事當作無可奈何而選擇遺忘，那莉奎蒂亞也會忘記這一切。"
L28_1.m_Talk_DEU = "Because if I deny it or forget it as something unavoidable, then Nequitia would forget it too."
L28_1.m_Talk_FRA = "Because if I deny it or forget it as something unavoidable, then Nequitia would forget it too."
