L30_1.m_Pos = "C"
L30_1.m_Talk_KOREA = "난 알아. 이 녀석도... 그 순간을 떠올릴 때마다 괴로워하는 게, 느껴지거든."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "私には分かる。こいつも……あの瞬間を思い出すたびに苦しむのが、伝わってくるんだ。"
L30_1.m_Talk_ENG = "I can tell. Every time that moment comes back to me... it hurts her too."
L30_1.m_Talk_TWN = "我知道。那傢伙……每次想起那一刻，都感到痛苦。"
L30_1.m_Talk_DEU = "I can tell. Every time that moment comes back to me... it hurts her too."
L30_1.m_Talk_FRA = "I can tell. Every time that moment comes back to me... it hurts her too."
