L41_1 = "...누군가는 말해줘야 하지 않을까? 레시피에 들어가는 재료를 멋대로 바꾸면 안 된다고."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "……誰か言ってやるべきじゃないのか？　料理の材料を勝手に変えるのはまずいと。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "...Shouldn't someone tell her she can't just substitute ingredients however she likes?"
L40_1.m_Talk_ENG = L41_1
L41_1 = "……是不是應該有人提醒她啊？跟她說不能隨便替換料理食材。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "...Shouldn't someone tell her she can't just substitute ingredients however she likes?"
L40_1.m_Talk_DEU = L41_1
