L42_1 = "...간식만 먹던 오르카가 제대로 끼니를 챙기기 시작했습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "……おやつばかり食べていたオルカが、ちゃんと食事を取るようになったんです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "...Orca used to live on snacks alone. Now she's eating proper meals."
L41_1.m_Talk_ENG = L42_1
L42_1 = "……原本只吃零食的奧爾卡，現在開始吃正餐了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "...Orca used to live on snacks alone. Now she's eating proper meals."
