L45_1 = "코핀 컴퍼니가 이곳에 전초를 세우도록 허락한 건 좋은 판단이었어, 부관."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "コフィンカンパニーがここに前哨基地を立てられるように許可したのは英断だった、副官。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Letting Coffin Company establish a forward base here was a good call, Adjutant."
L44_1.m_Talk_ENG = L45_1
L45_1 = "讓科芬公司在這裡設立前哨據點真是明智的判斷，副官。"
