L46_1 = "VIVIEN_OPR_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "L"
L46_1 = "관리국 접선책이 생긴 뒤로 이렇게 식량물자도 지원받고, 인재를 데려올 창구도 생겨난 덕에 수비대 형편이 제법 좋아졌네."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "管理局との繋がりができてからは、こうして食糧も支援してもらえるし、人材を連れてくる窓口ができたおかげで守備隊もかなり整ってきた。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Since we gained an Administration liaison, we've been receiving supply support like this. We also now have a channel for recruiting personnel. The Border Guards' situation has improved quite a bit."
L45_1.m_Talk_ENG = L46_1
L46_1 = "自從有了管理局的聯絡窗口，不僅獲得糧食支援，也有了引進人才的管道，守備隊的狀況也因此改善了不少。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "Since we gained an Administration liaison, we've been receiving supply support like this. We also now have a channel for recruiting personnel. The Border Guards' situation has improved quite a bit."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Since we gained an Administration liaison, we've been receiving supply support like this. We also now have a channel for recruiting personnel. The Border Guards' situation has improved quite a bit."
L45_1.m_Talk_FRA = L46_1
