L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "...그렇잖아도, 재건단에서 관리국과 교류 확대를 위한 안건을 추진하고 있어."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "……ちょうど、再建団で管理局との交流を拡大するための案件を進めている。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "As it happens, the Reconstruction Alliance is pushing an initiative to expand exchanges with the Administration."
L48_1.m_Talk_ENG = L49_1
L49_1 = "……正好，重建委員會正在推動與管理局擴大交流的提案。"
