L51_1 = "ELLA_BORDER_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "노르드나빅의 역사가 엑자일러 선조들로부터 시작됐다는 건, 이제 세상 모든 사람들이 알고 있으니까요. 저희만큼 그 첫발을 떼기 좋은 입장도 없죠."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "ノルドナビックの歴史がエグザイラーの先祖から始まったということは、今や世界中に知られていますからね。その第一歩を踏み出す役割として、私たちほどの適任者はいないでしょう。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Now that everyone knows Nordnavik's history began with Exile ancestors, we're in a better position than anyone else to take the first step."
L50_1.m_Talk_ENG = L51_1
L51_1 = "畢竟諾爾德萊比的歷史本來就是源自於流浪者的祖先，現在這已經是眾所皆知的事實了。在這方面，我們確實是最適合率先踏出第一步的那一方。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "Now that everyone knows Nordnavik's history began with Exile ancestors, we're in a better position than anyone else to take the first step."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Now that everyone knows Nordnavik's history began with Exile ancestors, we're in a better position than anyone else to take the first step."
L50_1.m_Talk_FRA = L51_1
