L1_1.m_Pos = "C"
L2_1 = "하지만 조심해야겠지. 그들도 우리와 같은 사람인 이상, 모든 엑자일러가 마냥 선한 마음을 품고 있진 않을 테니까."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "だが注意を怠るな。彼らも私たちと同じく人である以上、すべてのエグザイラーが善人とは限らないからな。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Still, we should be careful. They're people just like us. Not every Exile will be guided by goodwill."
L1_1.m_Talk_ENG = L2_1
L2_1 = "但還是必須小心。既然他們和我們一樣都是人，就不可能對所有流浪者都懷有善意。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "Still, we should be careful. They're people just like us. Not every Exile will be guided by goodwill."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Still, we should be careful. They're people just like us. Not every Exile will be guided by goodwill."
