L3_1 = "네퀴티아도... 우리가 오랫동안 지켜봐야 할 그런 인물 중 하나고."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ネキティアも……時間をかけて見守らねばならない対象の一人だ。"
