L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "...잔류 악단의 행방을 자네가 찾아낼 수 있다는 건가?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "……残留楽団の行方を、君が調べられるということか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "...You're saying you can locate the remaining Orchestra?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "……你有辦法找出殘留樂團的行蹤嗎？"
