L7_1 = "EP15_ACT4_EPILOGUE2@77#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 743
L6_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L6_1.m_bWaitClick = true
