L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L6_1.m_Pos = "C"
L7_1 = "맞아. 악단의 핵이 품은 선율을 듣는 건, 지휘자로서의 본능 같은 거니까."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ええ。楽団の核が持つ旋律を聞き分けるのは、指揮者としての本能みたいなものだから。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Yes. Hearing the melody contained within the Orchestra's core is like instinct for a conductor."
L6_1.m_Talk_ENG = L7_1
L7_1 = "可以。聆聽樂團核心蘊含的旋律，是身為指揮者的本能。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "Yes. Hearing the melody contained within the Orchestra's core is like instinct for a conductor."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Yes. Hearing the melody contained within the Orchestra's core is like instinct for a conductor."
L6_1.m_Talk_FRA = L7_1
