L8_1 = "EP15_ACT4_EPILOGUE2@78#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 743
L7_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L7_1.m_bWaitClick = true
