L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L7_1.m_Pos = "C"
L8_1 = "하지만 그들은 엑자일러가 아니라 그림자야. 찾고 싶다면 싸울 각오로 임해야 돼."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "でも彼らはエグザイラーじゃなくてシャドウだよ。見つけたいなら戦う覚悟が要る。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "But they're not Exiles. They're Shadows. If you want to find them, be prepared to fight."
L7_1.m_Talk_ENG = L8_1
L8_1 = "不過，他們不是流浪者，而是暗影。若想找出他們，就必須做好戰鬥的準備。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "But they're not Exiles. They're Shadows. If you want to find them, be prepared to fight."
L7_1.m_Talk_DEU = L8_1
L8_1 = "But they're not Exiles. They're Shadows. If you want to find them, be prepared to fight."
L7_1.m_Talk_FRA = L8_1
