L9_1 = "EP15_ACT4_EPILOGUE2@79#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 108
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 743
L8_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "VIVIEN_OPR_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "걱정 마라. 우리에겐 악단의 연주를 막아낼 수단이 있으니까."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "心配するな。私たちは楽団の演奏を止める手段を持っている。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Don't worry. We have ways to stop the Orchestra's performance."
L8_1.m_Talk_ENG = L9_1
L9_1 = "放心吧。我們已經有了能對抗樂團演奏的方法。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "Don't worry. We have ways to stop the Orchestra's performance."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Don't worry. We have ways to stop the Orchestra's performance."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP15_ACT4_EPILOGUE2@80#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 109
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 743
