L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "우리 남부국경수비대에겐 그 악단을 토벌해야만 할 의무가 있어."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "私たち南部国境守備隊には、あの楽団を討伐する義務があるんだ。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "The Southern Border Guards have a duty to eliminate them."
L9_1.m_Talk_ENG = L10_1
L10_1 = "南部國境守備隊，有義務討伐那個樂團。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "The Southern Border Guards have a duty to eliminate them."
L9_1.m_Talk_DEU = L10_1
L10_1 = "The Southern Border Guards have a duty to eliminate them."
