L13_1 = "CURIAN_BORDER_NULL_FAKE"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "L"
L13_1 = "레아 슈나이더. 자네 생각엔, 그 그림자들에게도 교화의 여지가 있다고 보나?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "レア・シュナイダー。君はあのシャドウたちにも更生の余地があると思うか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Leah Schneider. Do you believe those Shadows can still be rehabilitated?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "蕾亞．修奈德。依你看，那些暗影還有教化的可能嗎？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "Leah Schneider. Do you believe those Shadows can still be rehabilitated?"
L12_1.m_Talk_DEU = L13_1
