L13_1.m_Pos = "C"
L13_1.m_bCharPinup = true
L13_1.m_bCharPinupEasingTime = 0.3
L14_1 = "위험한 발상이야, 지휘관. 낙원문의 열쇠를 노리던 그 녀석을 생각하라고."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "それは危険な発想だ、指揮官。楽園の門の鍵を狙ったやつを思い出せ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "That's a dangerous idea, Commander. Remember the one who tried to seize the Key to Avalon's Gate?"
L13_1.m_Talk_ENG = L14_1
L14_1 = "這是很危險的想法，指揮官。請想想那個覬覦樂園之門鑰匙的傢伙。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "That's a dangerous idea, Commander. Remember the one who tried to seize the Key to Avalon's Gate?"
