L17_1 = "EP15_ACT4_EPILOGUE2@84#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 116
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 743
L16_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L16_1.m_Pos = "R"
L17_1 = "지휘자인 네퀴티아를 따랐을 뿐이라고 변호할 순 있겠지만... 그림자는 그림자일 뿐, 거기에 선악의 잣대를 들이밀 필요는 없어."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "あえて弁護するなら、あれは指揮者であるネキティアに従っただけとも言えるけど……シャドウはシャドウ。善悪の基準に当てはめる必要なんかない。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "You could argue they were only following their Chief Conductor, Nequitia... But a Shadow is still a Shadow. There's no need to apply moral judgment to them."
L16_1.m_Talk_ENG = L17_1
L17_1 = "雖然可以說他們只是追隨指揮者莉奎蒂亞……但暗影終究是暗影，沒有必要用善惡衡量。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "You could argue they were only following their Chief Conductor, Nequitia... But a Shadow is still a Shadow. There's no need to apply moral judgment to them."
L16_1.m_Talk_DEU = L17_1
L17_1 = "You could argue they were only following their Chief Conductor, Nequitia... But a Shadow is still a Shadow. There's no need to apply moral judgment to them."
L16_1.m_Talk_FRA = L17_1
