L17_1.m_Face = "UNIT_SERIOUS"
L17_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L17_1.m_Pos = "R"
L18_1 = "이용가치가 있느냐 없느냐, 그에 따라 처분은 당신들의 판단에 맡길게."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "利用価値があるかどうか、それによって処分はどうするか、その判断は君に任せるよ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Whether they're useful or not, I'll leave the decision to you."
L17_1.m_Talk_ENG = L18_1
L18_1 = "就由你來依據是否具有利用價值這點進行判斷。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "Whether they're useful or not, I'll leave the decision to you."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Whether they're useful or not, I'll leave the decision to you."
L17_1.m_Talk_FRA = L18_1
