L19_1 = "EP15_ACT4_EPILOGUE2@86#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 743
L18_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
