L19_1 = "CURIAN_BORDER_NULL_FAKE"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "L"
L19_1 = "...새겨두지. 한 달 뒤, 첫번째 좌표로 원정을 떠나게 될 테니 부디 자네도 함께 동참해주게나."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "……覚えておこう。1か月後、1つ目の座標へ遠征に出る。その時、ぜひ君も同行してほしい。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "...I understand. We depart for the first coordinates in one month. I hope you'll join us."
L18_1.m_Talk_ENG = L19_1
L19_1 = "……我會記住的。一個月後，我們將出發前往第一個座標進行遠征。希望你能同行。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "...I understand. We depart for the first coordinates in one month. I hope you'll join us."
L18_1.m_Talk_DEU = L19_1
L19_1 = "...I understand. We depart for the first coordinates in one month. I hope you'll join us."
L18_1.m_Talk_FRA = L19_1
