L34_1.m_Pos = "R"
L35_1 = "스스로 선택해서 온 것이니까요. 보잘 것 없는 요리실력이나마 그대들에게 도움이 되어 기쁩니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "わたくしが来たくて来たのですから。迷惑にならないか心配でしたが、こうしてお役に立ててよかったです。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "I chose to come here. I feared I might become a burden, but I'm relieved that I can help in any way."
L34_1.m_Talk_ENG = L35_1
L35_1 = "我是自己選擇來到這裡。我原本還擔心會成為負擔，幸好還能這樣幫上忙。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "I chose to come here. I feared I might become a burden, but I'm relieved that I can help in any way."
