L37_1.m_bCharPinupEasingTime = 0.3
L38_1 = "당신은... 우리와 비견될 수 없는 아주 먼 여정을 거쳐왔습니다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "あなたは……私たちとは比べ物にならないほど長い旅をして来られました。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "You have... traveled farther than any of us could imagine."
L37_1.m_Talk_ENG = L38_1
L38_1 = "你……經歷了我們無法比擬的漫長旅程。"
