L38_1.m_Pos = L39_1
L38_1.m_bCharPinup = true
L39_1 = "그 길의 끝에 다다른 곳이 이런 황량한 벌판이어도 괜찮은 것인지, 의문이 들더군요."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "その果てにたどり着いた場所が、こうも荒れ果てた野原で本当にいいのですか。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "I found myself wondering whether it was truly acceptable for the end of that journey to be a desolate plain such as this."
L38_1.m_Talk_ENG = L39_1
L39_1 = "旅途的終點竟是這樣一片荒涼之地，難道不會感到遺憾嗎？"
