L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "……遠い異郷のジャガイモは、楽園のものと味が違うのではないか心配でしたが、とても美味しいです。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "...I worried the potatoes might taste different from those of the Promised Land, but they are delicious."
L39_1.m_Talk_ENG = L40_1
L40_1 = "……我原本還擔心，遙遠異鄉的馬鈴薯是否會和樂園的不同，結果卻意外地美味。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "...I worried the potatoes might taste different from those of the Promised Land, but they are delicious."
L39_1.m_Talk_DEU = L40_1
L40_1 = "...I worried the potatoes might taste different from those of the Promised Land, but they are delicious."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP15_ACT4_EPILOGUE2@103#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 743
L40_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_Face = "UNIT_IDLE"
L40_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L40_1.m_Pos = "R_F_C"
L40_1.m_bCharPinup = true
L41_1 = "이곳에도 낙원의 들판만큼 아름다운 풍경이 있고, 낙원의 주민들만큼이나 친절한 사람들이 있습니다. 저는 이곳이 낙원과 다르지 않다고 생각합니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ここにも楽園の野原ほど美しい景色があり、楽園の住民ほど優しい人たちがいます。わたくしは、ここも楽園と大して変わらないと思っております。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "There are landscapes here as beautiful as the fields of the Promised Land, and people as kind as its residents. I believe this place is no different from there."
L40_1.m_Talk_ENG = L41_1
L41_1 = "這裡同樣擁有不遜於樂園田野的景色，也有如樂園居民般溫暖的人。在我看來，此地與樂園沒有差別。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "There are landscapes here as beautiful as the fields of the Promised Land, and people as kind as its residents. I believe this place is no different from there."
L40_1.m_Talk_DEU = L41_1
L41_1 = "There are landscapes here as beautiful as the fields of the Promised Land, and people as kind as its residents. I believe this place is no different from there."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP15_ACT4_EPILOGUE2@104#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 743
L41_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "CURIAN_BORDER_NULL_FAKE"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "L"
L41_1.m_bCharPinup = true
L42_1 = "노르드나빅의 겨울은 뼛속까지 시릴 정도로 매섭습니다. 낙원에는 존재하지 않던 혹독함일 테죠."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ノルドナビックの冬は骨の髄まで冷えるほど厳しい。楽園には存在しなかった過酷さでしょう。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Winter in Nordnavik bites to the bone. It must be a harshness that never existed in the Promised Land."
L41_1.m_Talk_ENG = L42_1
L42_1 = "諾爾德萊比的冬天寒冷刺骨，那是樂園從未存在的嚴酷。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "Winter in Nordnavik bites to the bone. It must be a harshness that never existed in the Promised Land."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Winter in Nordnavik bites to the bone. It must be a harshness that never existed in the Promised Land."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP15_ACT4_EPILOGUE2@105#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 142
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 743
L42_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Face = "UNIT_LAUGH"
L42_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L42_1.m_Pos = "R"
L42_1.m_bCharPinup = true
L43_1 = "하지만 그 겨울이 영원하지 않다는 걸 알기에 사람들은 용기를 가지고 견뎌냅니다. 시간이 흘러 녹은 땅에는 겨울을 이겨낸 씨앗들이 다시금 꽃을 피워낼 것입니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "ですがその冬が永遠に続くものではないと知っているからこそ、人々は勇気を出して耐えきるのです。時が経ち、雪解けを迎えた大地には、冬を乗り越えた種が再び花を咲かすでしょう。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "But because people know that winter is not eternal, they endure it with courage. When time passes and the frozen ground thaws, seeds that survived the winter will bloom once more."
L42_1.m_Talk_ENG = L43_1
L43_1 = "但正因為眾人知道寒冬終將過去，才得以懷抱勇氣堅持下去。待時光流轉、冰雪消融，戰勝寒冬的種子，終將再次綻放花朵。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "But because people know that winter is not eternal, they endure it with courage. When time passes and the frozen ground thaws, seeds that survived the winter will bloom once more."
L42_1.m_Talk_DEU = L43_1
L43_1 = "But because people know that winter is not eternal, they endure it with courage. When time passes and the frozen ground thaws, seeds that survived the winter will bloom once more."
L42_1.m_Talk_FRA = L43_1
L43_1 = {}
