L43_1.m_Face = "UNIT_IDLE"
L43_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L43_1.m_Pos = "R"
L43_1.m_bCharPinup = true
L44_1 = "그런 기적은... 낙원에서는 볼 수 없던 것이지요."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "そのような奇跡は……楽園では見られなかったものです。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Such miracles... were things one could not witness in the Promised Land."
L43_1.m_Talk_ENG = L44_1
L44_1 = "那樣的奇蹟……在樂園無法見到。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "Such miracles... were things one could not witness in the Promised Land."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Such miracles... were things one could not witness in the Promised Land."
