L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 743
L46_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L47_1 = "CURIAN_BORDER_NULL_FAKE"
L46_1.m_CharStrID = L47_1
L47_1 = "그렇기에, 이곳을 지켜내고 싶으신 겁니까?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "だから、ここを守り抜きたいと思われるのですか。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Is that why you wish to protect this place?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "所以，你才想守護這個地方嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "Is that why you wish to protect this place?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Is that why you wish to protect this place?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP15_ACT4_EPILOGUE2@108#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 743
L47_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L48_1 = "아우드라, 그녀가 어리석은 실패를 경험한 우리에게 또 한 번의 기회를 주었으니..."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "はい。アウドラ……彼女が愚かな失敗を経験したわたくしたちに、もう一度チャンスを与えてくれた……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Yes. Audra granted those of us who suffered a foolish failure another chance..."
L47_1.m_Talk_ENG = L48_1
L48_1 = "對。奧德拉，她又給了經歷愚蠢失敗的我們一個機會……"
L47_1.m_Talk_TWN = L48_1
L48_1 = "Yes. Audra granted those of us who suffered a foolish failure another chance..."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Yes. Audra granted those of us who suffered a foolish failure another chance..."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP15_ACT4_EPILOGUE2@109#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 743
L48_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L49_1 = "이번엔, 믿는 이들을 이끄는 대신 그들을 따르며 저의 모든 것을 바치려 하옵니다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "だから今度は、わたくしを信じる者を導くのではなく、彼らの意に従い、わたくしのすべてを捧げるつもりです。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "This time, rather than leading those who believe in me, I wish to follow them and devote all that I am."
L48_1.m_Talk_ENG = L49_1
L49_1 = "這一次，我不再引領信賴的人。而是選擇追隨他們，奉獻我的一切。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "This time, rather than leading those who believe in me, I wish to follow them and devote all that I am."
L48_1.m_Talk_DEU = L49_1
L49_1 = "This time, rather than leading those who believe in me, I wish to follow them and devote all that I am."
L48_1.m_Talk_FRA = L49_1
