L2_1 = "EP15_ACT4_EPILOGUE2@110#Talk"
L1_1.m_CutScenKey_Talk = L2_1
L2_1 = 151
L1_1.m_CutScenProcessKey = L2_1
L1_1.m_CutScenID = 743
L1_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L1_1.m_bWaitClick = true
L1_1.m_fWaitTime = 0
L1_1.m_Face = "UNIT_DESPAIR"
L2_1 = "CURIAN_BORDER_NULL_FAKE"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "이끄는 자가 되기를 포기하고, 그저 묵묵히 뒤를 따르는 그림자가 된다... 그것이 당신께서 찾은 속죄의 방식입니까?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "導く側になることを諦め、信じる者にただ黙々とついていく影になる……それが、あなたが見出した贖罪の仕方ですか。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "To abandon being the one who leads, and instead become a quiet shadow that follows those who believe... is that the form your atonement has taken?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "放棄成為引領者，只願默默成為追隨信賴之人的影子……這便是你選擇的贖罪方式嗎？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "To abandon being the one who leads, and instead become a quiet shadow that follows those who believe... is that the form your atonement has taken?"
L1_1.m_Talk_DEU = L2_1
L2_1 = "To abandon being the one who leads, and instead become a quiet shadow that follows those who believe... is that the form your atonement has taken?"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "EP15_ACT4_EPILOGUE2@111#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 152
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 743
L2_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "UNIT_HATE"
L2_1.m_Face = L3_1
L2_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L2_1.m_Pos = "C"
L3_1 = "...예. 저 자신을 믿은 대가가 얼마나 많은 이들을 지옥으로 밀어 넣었는지 이제는 알고 있나이다."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "……はい。わたくし自身を信じた代償として、あまりにも多くの人を地獄へ突き落としてしまったこと、今はよく分かっています。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "...Yes. I now understand how many souls were cast into ruin because I placed faith in myself."
L2_1.m_Talk_ENG = L3_1
L3_1 = "……對。我已經明白過去相信所付出的代價，是將多少人推入地獄。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "...Yes. I now understand how many souls were cast into ruin because I placed faith in myself."
L2_1.m_Talk_DEU = L3_1
L3_1 = "...Yes. I now understand how many souls were cast into ruin because I placed faith in myself."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP15_ACT4_EPILOGUE2@112#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 743
L3_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_DESPAIR"
L3_1.m_CharStrID = "MORS_SHADOW_NPC_GIRL"
L3_1.m_Pos = "C"
L4_1 = "이면의 어둠을 등진 채 빛을 바라보던 어리석은 저이기에... 더는 이끄는 사람이 되겠다는 오만을 부리지 않으려 하옵니다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "裏側の闇に背を向け、光ばかりを追いかけていた愚かなわたくしゆえ……もう人を導く者になろうなどという不遜な望みは抱かぬつもりです。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I was a foolish one who gazed only toward the light while turning my back upon the darkness behind it... I will never again commit the arrogance of seeking to lead."
L3_1.m_Talk_ENG = L4_1
L4_1 = "背對內心的陰暗、只注視光明的我愚蠢至極……如今，不會再傲慢地引領他人。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "I was a foolish one who gazed only toward the light while turning my back upon the darkness behind it... I will never again commit the arrogance of seeking to lead."
L3_1.m_Talk_DEU = L4_1
L4_1 = "I was a foolish one who gazed only toward the light while turning my back upon the darkness behind it... I will never again commit the arrogance of seeking to lead."
L3_1.m_Talk_FRA = L4_1
