L17_1 = "C_F_L"
L16_1.m_Pos = L17_1
L17_1 = "맞아. 장벽보수로 고생하다 돌아온 우리에겐, 보다 나은 대접을 받을 권리가 있다고."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "そうだ。障壁の報酬で疲れて帰ってきたオレたちには、もっとマシなもんを食う権利があるんだよ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "She's right. After spending all day repairing the barrier, we deserve better treatment than this."
L16_1.m_Talk_ENG = L17_1
L17_1 = "沒錯。辛苦修補完城牆的我們，應該有資格享受更好的待遇吧？"
L16_1.m_Talk_TWN = L17_1
