L18_1 = "오늘은 고생하는 모든 대원들을 위해 식사를 대접하고 싶으시다더군요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "今日は苦労している隊員全員に、食事をご馳走したいとのことです。"
