L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "자 자, 편식하지 말고 빨리 먹자고요. 다들 열심히 일하다 와서 잔뜩 배고픈 상태잖아요?"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "さあさあ、好き嫌いしないで、早く食べましょうよ。みんな仕事頑張ってお腹空いてるでしょう？"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Come on now. No picky eating. We're all exhausted from work and starving, aren't we?"
L20_1.m_Talk_ENG = L21_1
L21_1 = "好了好了，別挑食了，快吃吧。大家辛苦了一整天，肚子都餓壞了吧？"
