L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "C"
L45_1 = "시영 씨! 어떻게 표정 하나 안 바뀌고 그걸 먹을 수 있어요?! 깜빡 속았잖아요!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "シノンさん！　あれを顔色一つ変えずによく食べましたね！？　すっかり騙されたじゃないですか！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Shiyoung! How did you eat that without changing your expression?! You totally fooled me!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "時雨！你怎麼能面不改色地吃下去？！我被騙了！"
