L46_1 = "JOOSHIYOON_DELTA_NULL_NULL"
L45_1.m_CharStrID = L46_1
L45_1.m_Pos = "L"
L46_1 = "아하하, 귀한 음식을 먹는데 오만상을 쓸 순 없잖아요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "あはは、せっかくの料理をしかめっ面しながら食べるのは失礼じゃないですか。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Ahaha. You can't make faces when someone serves you something with care."
L45_1.m_Talk_ENG = L46_1
L46_1 = "哈哈，吃著難得的料理，不能露出難看的表情啊。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "Ahaha. You can't make faces when someone serves you something with care."
L45_1.m_Talk_DEU = L46_1
