L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "L"
L47_1 = "그러는 카린 양도, 계속 아무렇지 않게 드시던데요?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "そういうカリンさんだって、ずっと平気な顔で食べてましたよね？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Besides, Karin, you kept eating like nothing was wrong too."
L46_1.m_Talk_ENG = L47_1
L47_1 = "這麼說的卡琳小姐，不也是一直若無其事地吃著嗎？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "Besides, Karin, you kept eating like nothing was wrong too."
