L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "결국 에클레시아 씨가 정성 들여 만든 거니까 최소한 티는 안 내려고 했죠! 오르카 씨 몫인 줄 알았으면 절대 손 대지 않았을 거라고요!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "エクレシアさんが一生懸命作ってくださったものだから、せめて顔には出さないようにしてたんです！　オルカさんの分だと知っていたら、絶対に手を出してません！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "That's because Ecclesia made it with effort and I didn't want to be rude! If I'd known it was Orca's portion, I never would've touched it!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "因為那是艾可露西亞她辛苦做的，所以我盡力不表現出來啊！要是早知道是奧爾卡的份，我才不會碰呢！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "That's because Ecclesia made it with effort and I didn't want to be rude! If I'd known it was Orca's portion, I never would've touched it!"
