L9_1.m_Pos = "L"
L9_1.m_bCharPinup = true
L10_1 = "엑자일러란 이름을 처음 들었을 땐, 이곳 생활에 적응하기 힘들 거라 생각했네."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "エグザイラーという名を初めて聞いた時は、ここの生活に慣れるのは大変だろうと思っていた。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "When I first heard the name Exile, I thought they'd struggle to adapt to life here."
L9_1.m_Talk_ENG = L10_1
L10_1 = "當初聽說流浪者這個名字時，我還以為他們會很難適應這裡的生活。"
