L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "L"
L10_1.m_bCharPinup = true
L11_1 = "이국에서 온 것도 아닌, 다른 세상의 사람이니 말이야."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "異国でもない、異世界の人間だからな。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "After all, they're not merely foreigners. They're people from another world."
L10_1.m_Talk_ENG = L11_1
L11_1 = "畢竟不是來自異國，而是來自另一個世界。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "After all, they're not merely foreigners. They're people from another world."
L10_1.m_Talk_DEU = L11_1
L11_1 = "After all, they're not merely foreigners. They're people from another world."
L10_1.m_Talk_FRA = L11_1
