L12_1 = "EP15_ACT4_EPILOGUE2@159#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 211
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 743
L11_1.m_CutScenStrID = "EP15_ACT4_EPILOGUE2"
L11_1.m_bWaitClick = true
