L11_1.m_Face = "UNIT_PRIDE"
L12_1 = "VIVIEN_OPR_NULL_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "R"
L11_1.m_bCharPinup = true
L12_1 = "사람 사는 곳은 다 똑같다- 뭐 그런 뻔한 얘기네. 관리국이 양자위상차의 개념을 없애버렸다고 했으니, 언젠가 떠나야 할 필요도 없을 테고."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "人の暮らしなど、どこでも同じということか。管理局が量子位相差の概念を消したから、いつかここを去る必要もないだろうしな。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "People are the same wherever you go—some cliche like that. Besides, the Administration eliminated the concept of quantum phase divergence. It's not like they'll eventually have to leave."
L11_1.m_Talk_ENG = L12_1
L12_1 = "人在哪都一樣—這已經是老掉牙的說法罷了。既然管理局已經消除了量子相位差，未來也不必再離開了。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "People are the same wherever you go—some cliche like that. Besides, the Administration eliminated the concept of quantum phase divergence. It's not like they'll eventually have to leave."
L11_1.m_Talk_DEU = L12_1
L12_1 = "People are the same wherever you go—some cliche like that. Besides, the Administration eliminated the concept of quantum phase divergence. It's not like they'll eventually have to leave."
L11_1.m_Talk_FRA = L12_1
