L12_1.m_fTalkTime = 0.03
L13_1 = "去る必要がないなら、なぜ次元艦船を修理する間だけここに滞在するんですか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "If they don't need to leave, then why did they say they'd only stay here until the dimensional ship is repaired?"
L12_1.m_Talk_ENG = L13_1
L13_1 = "既然他們不必離開，為什麼他們只打算在修好次元艦船的期間暫時停留？"
