L13_1 = "If they don't need to leave, then why did they say they'd only stay here until the dimensional ship is repaired?"
L12_1.m_Talk_DEU = L13_1
L13_1 = "If they don't need to leave, then why did they say they'd only stay here until the dimensional ship is repaired?"
