L22_1.m_CharStrID = L23_1
L23_1 = "결국 저들이 온 곳이 평행세계라면, 이름은 달라도 돌아갈 익숙한 장소가 있을 테니까."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "平行世界から来たのなら、名は違えど、戻るべき懐かしい場所があるはずだからな。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "If they really came from a parallel world, then even if the names differ, there must still be familiar places waiting for them."
L22_1.m_Talk_ENG = L23_1
L23_1 = "畢竟來自平行世界，即使名字不同，也有自己要回去的熟悉的地方。"
