L26_1 = "하아... 숨 차. 시영 씨. 이게 이렇게까지 멀리 도망칠 일이예요?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "はあ……息切れが。シノンさん、さっきのってこんなに遠くまで逃げることですか？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "*Huff...* I'm out of breath. Shiyoung, did we really need to run this far?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "哈啊……累死了。時雨，有必要逃到這麼遠嗎？"
